#!/bin/bash
# RTL simulation of the TOE (toe_top) with xsim.
#
# Usage:
#   ./run_sim.sh                 # run all tests
#   ./run_sim.sh <testname>...   # run selected test(s)
#   DUMP=1 ./run_sim.sh <test>   # also dump VCD (tb_toe_top.vcd in run dir)
#
# Tests: passive_open active_open rx_out_of_order fast_retransmit
#        rst_handling zero_window
#
# Prerequisite: synthesized RTL in ../../build10g/hls/toe/toe_prj/solution1/syn/verilog
# (generated by ../../build_toe_10g.sh)

set -e

VIVADO_SETTINGS=${VIVADO_SETTINGS:-/home/nvm/tools/Vivado/2022.1/settings64.sh}
SCRIPT_DIR=$(cd "$(dirname "$0")" && pwd)
REPO_ROOT=$(cd "${SCRIPT_DIR}/../.." && pwd)

# NO_RX_BYPASS=1: use the RX_DDR_BYPASS=0 build (build10g_nb by default) and
# compile the TB with the matching port set / test expectations
TB_DEFINES=""
if [ -n "${NO_RX_BYPASS}" ]; then
    TB_DEFINES="-d NO_RX_BYPASS"
    RTL_DIR=${RTL_DIR:-${REPO_ROOT}/build10g_nb/hls/toe/toe_prj/solution1/syn/verilog}
    WORK_TAG=${WORK_TAG:-_nb}
fi
RTL_DIR=${RTL_DIR:-${REPO_ROOT}/build10g/hls/toe/toe_prj/solution1/syn/verilog}

ALL_TESTS="passive_open active_open rx_out_of_order fast_retransmit rst_handling zero_window port_release opt_parser_robust buffer_wrap window_update pure_fin_close mss_option tx_segmentation fast_recovery sack_selective_rtx half_close ts_negotiate paws_drop time_wait_ack isn_quality"
# tests that only exist in the RX_DDR_BYPASS=0 build
if [ -n "${NO_RX_BYPASS}" ]; then
    ALL_TESTS="${ALL_TESTS} rx_ooo_overlap seq_window_check sack_rx_gen"
fi
TESTS="${*:-$ALL_TESTS}"

if [ ! -f "${RTL_DIR}/toe_top.v" ]; then
    echo "ERROR: RTL not found in ${RTL_DIR}. Run build_toe_10g.sh first." >&2
    exit 1
fi

# shellcheck disable=SC1090
source "${VIVADO_SETTINGS}"

# WORK_TAG separates compile outputs when switching RTL_DIR (e.g. WORK_TAG=_sim)
WORK_DIR="${SCRIPT_DIR}/run${WORK_TAG}"
mkdir -p "${WORK_DIR}"
cd "${WORK_DIR}"

# $readmemh in the HLS RTL uses relative "./*.dat" paths
for f in "${RTL_DIR}"/*.dat; do
    ln -sf "$f" .
done

# ---- compile (only when RTL or TB is newer than the last compile) ----
STAMP=compile.stamp
NEED_COMPILE=0
if [ ! -f ${STAMP} ]; then
    NEED_COMPILE=1
else
    for f in "${RTL_DIR}"/*.v "${SCRIPT_DIR}"/tb_toe_top.sv; do
        if [ "$f" -nt ${STAMP} ]; then NEED_COMPILE=1; break; fi
    done
fi

if [ ${NEED_COMPILE} -eq 1 ]; then
    echo "=== xvlog: compiling RTL + TB ==="
    xvlog "${RTL_DIR}"/*.v > xvlog_rtl.log 2>&1 || { tail -30 xvlog_rtl.log; exit 1; }
    xvlog -sv ${TB_DEFINES} "${SCRIPT_DIR}/tb_toe_top.sv" > xvlog_tb.log 2>&1 || { tail -40 xvlog_tb.log; exit 1; }
    echo "=== xelab: elaborating ==="
    xelab tb_toe_top -s tb_toe_snap --timescale 1ns/1ps -stats \
        > xelab.log 2>&1 || { tail -40 xelab.log; exit 1; }
    touch ${STAMP}
else
    echo "=== compile up-to-date, skipping ==="
fi

# ---- run ----
PASS=0
FAIL=0
FAILED_TESTS=""
for t in ${TESTS}; do
    echo ""
    echo "=== running test: $t ==="
    PLUSARGS=(--testplusarg "TESTNAME=$t")
    if [ -n "${DUMP}" ]; then PLUSARGS+=(--testplusarg "DUMP"); fi
    xsim tb_toe_snap -R "${PLUSARGS[@]}" > "xsim_${t}.log" 2>&1 || true
    if grep -q "TEST $t : PASS" "xsim_${t}.log"; then
        echo "    PASS"
        PASS=$((PASS+1))
    else
        echo "    FAIL  (see ${WORK_DIR}/xsim_${t}.log)"
        grep -E "TB-ERROR|TB-CHECK-FAIL|watchdog" "xsim_${t}.log" | head -10
        FAIL=$((FAIL+1))
        FAILED_TESTS="${FAILED_TESTS} $t"
    fi
done

echo ""
echo "==============================================="
echo " results: PASS=${PASS} FAIL=${FAIL}${FAILED_TESTS:+  failed:${FAILED_TESTS}}"
echo "==============================================="
[ ${FAIL} -eq 0 ]
